<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import * as api from '@/api/practice-paper'
import type {ComponentAttempt} from '@/api/practice-paper'
import {businessGet} from '@/api/business'
import {errorMessage} from '@/api/identity'
import '@/styles/practice-paper.css'
const route=useRoute(),router=useRouter(),paper=ref<api.PaperView|null>(null),versions=ref<api.PaperView[]>([]),candidates=ref<api.Candidate[]>([]),preview=ref<ComponentAttempt[]>([]),busy=ref(false),error=ref(''),saved=ref('')
const input=ref<api.PaperInput>({title:'',examCode:'CET4',year:2024,month:6,sourceNote:'',components:api.slots.map(slot=>({slot,setVersionId:''}))})
const dirty=computed(()=>JSON.stringify(input.value)!==saved.value),complete=computed(()=>input.value.title.trim()&&input.value.sourceNote.trim()&&input.value.components.every(c=>c.setVersionId))
let epoch=0
function apply(p:api.PaperView){paper.value=p;input.value={title:p.title,examCode:p.examCode,year:p.year,month:p.month,sourceNote:p.sourceNote,components:p.components.map(c=>({...c}))};saved.value=JSON.stringify(input.value);preview.value=[]}
async function options(){const n=epoch;const result=await api.adminComponents(new URLSearchParams({exam:'CET4',year:String(input.value.year),month:String(input.value.month)}));if(n===epoch)candidates.value=result}
async function load(){const n=++epoch;busy.value=true;error.value='';paper.value=null;versions.value=[];preview.value=[];try{if(route.params.id!=='new'){const p=await api.adminPaper(String(route.params.id));if(n!==epoch)return;apply(p);versions.value=await api.paperVersions(p.id)}else{input.value={title:'',examCode:'CET4',year:2024,month:6,sourceNote:'',components:api.slots.map(slot=>({slot,setVersionId:''}))};saved.value=JSON.stringify(input.value)}await options()}catch(e){if(n===epoch)error.value=errorMessage(e)}finally{if(n===epoch)busy.value=false}}
function type(slot:string){return slot.startsWith('DETAILED')?'DETAILED':slot}
async function dateChange(){preview.value=[];input.value.components.forEach(c=>c.setVersionId='');busy.value=true;try{await options()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function save(){busy.value=true;error.value='';try{const p=paper.value?await api.savePaper(paper.value.id,{...input.value,expectedLockVersion:paper.value.lockVersion}):await api.createPaper(input.value);apply(p);if(route.params.id==='new')await router.replace('/admin/practice/papers/'+p.id)}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function action(kind:'review'|'publish'|'unpublish'){if(!paper.value||dirty.value)return;busy.value=true;error.value='';try{apply(await api.paperAction(paper.value.id,kind,paper.value.lockVersion));versions.value=await api.paperVersions(paper.value!.id)}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function showPreview(){if(!paper.value||dirty.value)return;busy.value=true;error.value='';try{preview.value=await businessGet<ComponentAttempt[]>('/api/v1/admin/practice/papers/'+paper.value.id+'/preview')}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
function guard(){return !dirty.value||window.confirm('整卷草稿尚未保存，确定离开？')}
function unload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
watch(()=>route.params.id,load,{immediate:true});window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>{epoch++;window.removeEventListener('beforeunload',unload)});onBeforeRouteLeave(guard);onBeforeRouteUpdate(guard)
</script>
<template><section class="practice-page paper-page"><RouterLink to="/admin/practice/papers">← 返回整卷管理</RouterLink><header class="paper-heading"><h1>{{paper?'编辑整卷':'新建整卷'}}</h1><p>选择冻结题组版本，不复制题目。修改草稿后须重新确认组合来源。</p></header><p v-if="error" class="paper-error" role="alert">{{error}}</p><form class="paper-panel" @submit.prevent="save"><fieldset :disabled="busy" style="border:0;padding:0;min-width:0"><label class="paper-admin-field">整卷标题<input v-model="input.title" maxlength="180" required></label><div class="paper-admin-dates"><label class="paper-admin-field">考试类别<select disabled><option>四级</option></select></label><label class="paper-admin-field">年份<input v-model.number="input.year" type="number" min="2000" max="2100" required @change="dateChange"></label><label class="paper-admin-field">月份<select v-model.number="input.month" @change="dateChange"><option v-for="m in [12,9,7,6,3]" :key="m" :value="m">{{m}}月</option></select></label></div><label v-for="c in input.components" :key="c.slot" class="paper-admin-field">{{api.slotLabels[c.slot]}}<select v-model="c.setVersionId" required><option value="">选择已发布版本</option><option v-if="c.setVersionId&&!candidates.some(v=>v.setVersionId===c.setVersionId)" :value="c.setVersionId">已选冻结版本 {{c.setVersionId}}（当前不可用）</option><option v-for="v in candidates.filter(v=>v.type===type(c.slot))" :key="v.setVersionId" :value="v.setVersionId">{{v.title}} · v{{v.revision}} · {{v.questionCount}}题</option></select><small v-if="candidates.find(v=>v.setVersionId===c.setVersionId)" class="paper-muted">{{candidates.find(v=>v.setVersionId===c.setVersionId)?.sourceNote}}</small></label><label class="paper-admin-field">组合来源与套次说明<textarea v-model="input.sourceNote" required maxlength="2000" placeholder="说明所选来源、不同网站套次差异及使用范围。"></textarea></label><div class="paper-actions"><button class="paper-primary" type="submit" :disabled="!complete">保存草稿</button><span role="status">{{busy?'正在处理…':dirty?'有未保存修改':'草稿已保存'}}</span></div></fieldset></form><section v-if="paper" class="paper-panel" style="margin-top:20px"><h2>校对与发布</h2><p>{{paper.status==='PUBLISHED'?'已发布':paper.status==='UNLISTED'?'已下架':'未发布'}} · 发布版本 {{paper.revision}}</p><p v-if="dirty" class="paper-muted">请先保存当前修改，再预览或校对。</p><p v-for="check in paper.checks" :key="check" class="paper-muted">{{check}}</p><div class="paper-actions"><button :disabled="busy||dirty" @click="showPreview">预览组成与参考</button><button :disabled="busy||dirty" @click="action('review')">确认整卷组成与来源</button><button class="paper-primary" :disabled="busy||dirty||!paper.sourceReviewed" @click="action('publish')">发布新版本</button><button :disabled="busy||dirty||!paper.paperVersionId||paper.status==='UNLISTED'" @click="action('unpublish')">下架整卷</button></div><details v-for="c in preview" :key="c.slot" class="paper-reference"><summary>{{api.slotLabels[c.slot]}} · {{c.title}}</summary><template v-if="c.objective"><p v-for="p in c.objective.article?.content.paragraphs" :key="p.key">{{p.sentences.map(s=>s.text).join(' ')}}</p><p v-if="c.objective.wordBank?.length">词库：{{c.objective.wordBank.join(' / ')}}</p><div v-for="q in c.objective.questions" :key="q.id"><h3>{{q.stem}}</h3><p v-for="(o,i) in q.options" :key="i">{{String.fromCharCode(65+i)}}. {{o}}</p><p class="paper-muted">答案：{{c.objective.answers.find(a=>a.questionId===q.id)?.correctOption}} · {{c.objective.answers.find(a=>a.questionId===q.id)?.explanation}}</p></div></template><template v-else><p>{{c.prompt?.prompt}}</p><p>{{c.prompt?.requirements}}</p><p>{{c.reference}}</p><p>{{c.notes}}</p></template></details><details class="paper-reference"><summary>发布版本记录</summary><div v-for="v in versions" :key="v.paperVersionId||v.id"><h3>v{{v.revision}} · {{v.title}}</h3><p class="paper-muted">{{v.sourceNote}}</p><p v-for="c in v.componentDetails" :key="c.slot">{{api.slotLabels[c.slot]}}：{{c.title}}（版本ID {{c.setVersionId}}）</p></div></details></section></section></template>

